private void readInputStream(final InputStream in, final ByteBuffer buf) throws IOException {
    int bytesToRead = buf.remaining();
    byte[] bytes = new byte[bytesToRead];
    int totalBytesRead = in.read(bytes);

    while (totalBytesRead < bytesToRead) {
        int bytesRead = in.read(bytes, totalBytesRead, bytesToRead - totalBytesRead);
        if (bytesRead == -1) {
            break;
        }
        totalBytesRead += bytesRead;
    }

    if (totalBytesRead > 0) {
        buf.put(bytes, 0, totalBytesRead);
    }
}

