public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Load thread snapshots from file
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] tokens = line.split(",");
            // If any of the time range conditions are not met, skip the line
            if (!meetsTimeRangeCondition(tokens, timeRanges)) {
                continue;
            }
            // Create a new ThreadSnapshot object and add it to the list
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(tokens[0], tokens[1], tokens[2],
                    tokens[3], tokens[4], tokens[5], tokens[6], tokens[7], tokens[8]);
            threadSnapshots.add(threadSnapshot);
        }
    }
    return threadSnapshots;
}

private static boolean meetsTimeRangeCondition(String[] tokens, List<ProfileAnalyzeTimeRange> timeRanges) {
    long timestamp = Long.parseLong(tokens[8]);
    for (ProfileAnalyzeTimeRange range : timeRanges) {
        if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
            return true;
        }
    }
    return false;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("File is null or does not exist");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges are null or empty");
    }
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (FileInputStream fis = new FileInputStream(file)) {
        byte[] buffer = new byte[(int) file.length()];
        fis.read(buffer);
        ByteBuffer byteBuffer = ByteBuffer.wrap(buffer);
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            timeRange.setStartTime(byteBuffer.getLong());
            timeRange.setEndTime(byteBuffer.getLong());
            TimeStamp suffixTimestamp = new TimeStamp(timeRange.getStartTime());
            ThreadSnapshot threadSnapshot = new ThreadSnapshot(suffixTimestamp);
            threadSnapshots.add(threadSnapshot);
        }
        return threadSnapshots;
    } catch (IOException e) {
        throw new IOException("Unable to parse thread snapshots from file", e);
    } finally {
        file.delete();
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
